// Two resident V1 chains; native learned control and pure-content learning.
#define AKD_FP_CONTENT_HELPERS_ONLY
#include "silhouette_actor.cpp"
#include "dma_desc_ops.h"
#include "dma_engine_ops.h"
static int SOURCE_UNITS=0,CONTENT_INPUTS=0,RAW_WORDS=0,PAYLOAD_WORDS=0;
struct SepBank{
 int k,n,u;CPU cpu;std::vector<uint32_t>initial,infer,learn,retire;std::vector<int32_t>threshold;
 SepBank(int index,const std::string&p):k(index),n(index?CONTENT_INPUTS:1024),u(index?8:SOURCE_UNITS),cpu(n,u,32,index?1:2,load<uint32_t>(p+".ram")),initial(cpu.ram),infer(load<uint32_t>(p+".infer")),learn(load<uint32_t>(p+".learn")),threshold(load<int32_t>(p+".threshold")){if(k)retire=load<uint32_t>(p+".retire");}
 std::vector<int32_t>forward(const std::vector<uint8_t>&x,int label,int cap=24){need(x.size()==size_t(n),"separated bank input shape");std::vector<uint32_t>v(n/32);for(int j=0;j<n;j++){need(x[j]<=1,"fixture binary operands");v[j/32]|=uint32_t(x[j])<<(j%32);}auto old=cpu.ram;auto p=cpu.forward(v,label<0?0:label,label>=0);if(k&&label>=0)for(int j=0;j<u;j++){int b=2+j*cpu.stride;if(!std::equal(old.begin()+b+4,old.begin()+b+cpu.stride,cpu.ram.begin()+b+4))cpu.ram[b+3]=(uint32_t(std::min(p[j],cap))<<16)|(cpu.ram[b+3]&65535);}return p;}
 std::vector<uint8_t>activate(const std::vector<int32_t>&p){std::vector<uint8_t>x(u);for(int j=0;j<u;j++)x[j]=p[j]>threshold[j];return x;}
};
int main(int argc,char**argv){
 std::signal(SIGTERM,owned_stop);std::signal(SIGINT,owned_stop);std::unique_ptr<LabDriver>d;akida::HardwareDevicePtr dev;
 try{
  need(argc==5,"cpu/native fixture prefix count");std::string mode=argv[1],f=argv[2],out=argv[3];int count=std::stoi(argv[4]);need((mode=="cpu"||mode=="native")&&count>0&&count<=6000,"bounded separated manager cell");{int n0,u1;std::ifstream geometry(f+"/geometry.txt");geometry>>n0>>SOURCE_UNITS>>CONTENT_INPUTS>>u1>>RAW_WORDS>>PAYLOAD_WORDS;need(bool(geometry)&&n0==1024&&u1==8&&RAW_WORDS>=PAYLOAD_WORDS+256,"qualified sparse geometry");}auto inputs=load<uint8_t>(f+"/inputs.bin");auto nets=load<int32_t>(f+"/nets.bin"),modes=load<int32_t>(f+"/modes.bin"),labels=load<int32_t>(f+"/labels.bin"),external=load<int32_t>(f+"/externals.bin");need(inputs.size()==size_t(count*1024)&&nets.size()==size_t(count)&&modes.size()==size_t(count)&&labels.size()==size_t(count)&&external.size()==size_t(count),"sealed manager inputs");int normalcap;{std::ifstream capfile(f+"/normal_cap.txt");capfile>>normalcap;need(bool(capfile)&&(normalcap==24||normalcap==30),"sealed normal competition cap");}std::vector<SepBank>banks;for(int k=0;k<2;k++)banks.emplace_back(k,f+"/bank"+std::to_string(k));std::vector<std::vector<int8_t>>w;std::vector<std::vector<int32_t>>t;for(int j=0;j<3;j++){w.push_back(load<int8_t>(f+"/fixed_layer"+std::to_string(j)+".weights"));t.push_back(load<int32_t>(f+"/fixed_layer"+std::to_string(j)+".threshold"));}std::vector<std::vector<uint32_t>>epg;std::vector<std::vector<std::vector<uint32_t>>>ingress(2);for(int k=0;k<2;k++){epg.push_back(load<uint32_t>(f+"/role"+std::to_string(k)+".epg"));int n;std::ifstream ff(f+"/role"+std::to_string(k)+".ingress_count");ff>>n;need(bool(ff)&&n==3,"three compiler ingress tracks");for(int j=0;j<n;j++)ingress[k].push_back(load<uint32_t>(f+"/role"+std::to_string(k)+".ingress"+std::to_string(j)));}int nf;{std::ifstream ff(f+"/fixed_count.txt");ff>>nf;need(bool(ff)&&nf==4,"four fixed weight banks");}std::vector<std::vector<uint32_t>>fixed;for(int j=0;j<nf;j++)fixed.push_back(load<uint32_t>(f+"/fixed"+std::to_string(j)+".ram"));auto program=load<uint8_t>(f+"/model.bin");std::array<uint32_t,3>buf{};uint32_t previous=0,job=0;std::unique_ptr<akida::dma::Hrc>hrc;std::vector<uint32_t>mailbox(RAW_WORDS);
  if(mode=="native"){
   d=std::make_unique<LabDriver>();d->dma_read_min=128;dev=akida::HardwareDevice::create(d.get());auto info=dev->program(program.data(),program.size());need(info.number_of_passes()==1&&info.can_learn()&&info.input_is_dense()&&info.output_is_dense()&&!info.activation_enabled(),"single-pass resident union");dev->toggle_learn(true);need(dev->set_batch_size(4,false)==4,"four hardware queue slots");auto impl=static_cast<akida::HardwareDeviceImpl*>(dev.get());impl->pipeline(false);akida::dma::Engine eng(LabDriver::REG+0x28000,64,32);eng.descriptor_base_addr=d->read32(eng.reg_base_addr+8);need(eng.descriptor_base_addr>=LabDriver::RAM+256,"actual SDK queue");hrc=std::make_unique<akida::dma::Hrc>(eng);akida::dma::toggle_engine(d.get(),eng.reg_base_addr,true);for(auto&x:buf)x=dev->scratch_alloc(4*RAW_WORDS+32);
  }
  auto capture=[&](const std::vector<uint32_t>&p){auto v=p;auto impl=static_cast<akida::HardwareDeviceImpl*>(dev.get());akida::dma::dma_config_read(v.data()+2,v.size()-2,v.data(),impl->dma_config(),impl->mem(),d.get(),true);return v;};
  if(dev){for(int k=0;k<2;k++){auto v=capture(banks[k].initial);dump(out+".initial"+std::to_string(k),v);need(v==banks[k].initial,"initial learner RAM exact");}for(int j=0;j<nf;j++){auto v=capture(fixed[j]);dump(out+".fixed"+std::to_string(j)+".initial",v);need(v==fixed[j],"initial fixed RAM exact");}}
  for(int i=0;i<count;i++){
   kick_watchdog();int k=nets[i],phase=modes[i],label=labels[i];need(k>=0&&k<2&&label>=0&&label<(k?1:2),"role and teaching label");need(k?(phase>=0&&phase<=2):(phase==-1||phase==0),"fixed learning role");need(external[i]==0||(external[i]==1&&k==0),"external observations only to control chain");int n=k?CONTENT_INPUTS:1024,u=k?8:RAW_WORDS;std::vector<uint8_t>x(inputs.begin()+1024*i,inputs.begin()+1024*i+n);if(!external[i]){need(previous!=0||!dev,"native mailbox already produced");auto expected=(uint8_t*)mailbox.data()+(k?0:4*PAYLOAD_WORDS);for(int j=0;j<n;j++)need(x[j]==expected[j],"CPU fixture feedback exact");}
   auto pot=banks[k].forward(x,k?(phase?0:-1):(phase==0?label:-1),k&&phase==2?1:normalcap);auto a=banks[k].activate(pot);if(!k)for(int j=0;j<3;j++)a=fixed_layer(a,w[j],t[j]);std::vector<uint32_t>want(a.begin(),a.end()),got=want;append(out+".derived_potentials"+std::to_string(k),pot);
   if(dev){auto impl=static_cast<akida::HardwareDeviceImpl*>(dev.get());for(auto&p:ingress[k]){need(p.size()==3&&p[0]==0x88,"qualified ingress profile");akida::dma::dma_config_write(p.data(),p.size(),impl->dma_config(),impl->external_mem(),d.get(),true);}for(size_t j=0;j<epg[k].size();j+=2)d->write32(LabDriver::REG+0x40000+epg[k][j],epg[k][j+1]);auto&cfg=k?(phase==2?banks[k].retire:phase?banks[k].learn:banks[k].infer):(phase==0?banks[k].learn:banks[k].infer);need(cfg.size()==52,"global learning parameters only");akida::dma::dma_config_write(cfg.data(),cfg.size(),impl->dma_config(),impl->external_mem(),d.get(),true);
    uint32_t src;if(external[i]){src=buf[0]+32;d->write(src,x.data(),1024);}else src=previous+(k?0:4*PAYLOAD_WORDS);
    uint32_t dst=k?previous+4*(PAYLOAD_WORDS+240):(previous==buf[1]+32?buf[2]:buf[1]);std::vector<uint8_t>raw(n);d->read(src,raw.data(),raw.size());append(out+".actual_inputs"+std::to_string(k),raw);for(int j=0;j<n;j++)if(k||j<960||j>=992)need(raw[j]==x[j],"actual defined input fields exact; only native return-header bytes ignored by all weights");auto desc=akida::dma::format_input_desc(*hrc,++job,src,n/4,dst,uint32_t(label+1),akida::Shape{1,1,uint32_t(n)},0,0);need(desc.size()==16&&desc[1]==src&&desc[7]==dst,"input/output pointers exact");need(!k||((desc[8]>>16)&1023)==1,"constant content teacher0");append(out+".descriptors",desc);akida::dma::enqueue_descriptor(d.get(),hrc->engine,desc);auto until=Clock::now()+std::chrono::seconds(2);while((d->read32(hrc->engine.reg_base_addr+0x10)>>16)!=job){kick_watchdog();need(Clock::now()<until,"manager completion timeout");}std::vector<uint32_t>head(8);d->read(dst,head.data(),32);d->read(dst+32,got.data(),4*u);append(out+".native_headers",head);append(out+".native_payloads",got);append(out+".completed_indices",std::vector<uint32_t>{uint32_t(i)});std::vector<uint32_t>padded(RAW_WORDS);std::copy(got.begin(),got.end(),padded.begin());append(out+".outputs",padded);
    if(k){std::vector<uint32_t>after(RAW_WORDS);d->read(previous,after.data(),4*RAW_WORDS);for(int j=0;j<RAW_WORDS;j++)if(j<PAYLOAD_WORDS+240||j>=PAYLOAD_WORDS+256)need(after[j]==mailbox[j],"content/control outside return slot unchanged");need(std::equal(got.begin(),got.end(),after.begin()+PAYLOAD_WORDS+248),"native recall return slot exact");append(out+".mailboxes",after);}else previous=dst+32;
    for(int j=0;j<2;j++){auto v=capture(banks[j].initial);append(out+".states"+std::to_string(j),v);need(v==banks[j].cpu.ram,"complete learned native RAM differs");}need(got==want,"native separated output differs");
   }else{std::vector<uint32_t>pad(RAW_WORDS);std::copy(got.begin(),got.end(),pad.begin());append(out+".outputs",pad);for(int j=0;j<2;j++)append(out+".states"+std::to_string(j),banks[j].cpu.ram);}
   if(!k)mailbox=got;else std::copy(got.begin(),got.end(),mailbox.begin()+PAYLOAD_WORDS+248);
  }
  if(dev){for(int j=0;j<nf;j++){auto v=capture(fixed[j]);dump(out+".fixed"+std::to_string(j)+".final",v);need(v==fixed[j],"fixed routing weights changed");}for(auto b:buf)dev->scratch_free(b);dev->unprogram();}
  std::cout<<"{\"status\":\"PASS\",\"events\":"<<count<<",\"CPU_feedback_copies\":0,\"all_outputs_and_full_RAM_exact\":true,\"native_mailbox_return\":true}\n";
 }catch(const std::exception&e){if(dev)try{dev->unprogram();}catch(...){}std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}
}
